    ["note_flow_application_detected"] = "\"アプリケーション検出\"コールバックは、アプリケーションの検出直後に実行されます。これは、パケットインタフェースの場合はフローの最初の12パケット内で、ZMQインタフェースの場合はフローが受信された直後に発生します。",
