    ["toggle_use_mac_in_flow_key_title"] = "フローキーにMACアドレスを使用",
    ["toggle_users_rrds_description"] = "定義済みのユーザー用のバイトおよびアプリケーションタイムシリーズの作成を切り替えます。",
